package com.yongdrel.email_template_service.function;
import org.junit.jupiter.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class EmailTemplateFunctionTest{private final EmailTemplateFunction f=new EmailTemplateFunction();
 @Test void rendersEveryTemplate(){Map<String,Map<String,String>> all=Map.of("REGISTRATION_WELCOME",Map.of(),"PAYMENT_PROOF_RECEIVED",Map.of("orderId","O1"),"PAYMENT_APPROVED",Map.of("orderId","O1"),"PAYMENT_REJECTED",Map.of("orderId","O1","reason","No match"),"TICKET_CONFIRMATION",Map.of("orderId","O1","eventName","Draw"),"LOTTERY_DRAW_ANNOUNCEMENT",Map.of("eventName","Draw"),"WINNER_NOTIFICATION",Map.of("eventName","Draw","prize","Gold"),"ORDER_EXPIRATION",Map.of("orderId","O1"));for(var e:all.entrySet()){var r=f.renderEmailTemplate().apply(new EmailTemplateFunction.EmailRequest(e.getKey(),"Name","en",e.getValue()));assertFalse(r.subject().isBlank());assertFalse(r.htmlBody().isBlank());assertFalse(r.plainTextBody().isBlank());}}
 @Test void escapesHtml(){var r=f.render(new EmailTemplateFunction.EmailRequest("REGISTRATION_WELCOME","<img>","en",Map.of()));assertTrue(r.htmlBody().contains("&lt;img&gt;"));assertFalse(r.htmlBody().contains("<img>"));}
 @Test void rejectsMissingVariable(){assertThrows(IllegalArgumentException.class,()->f.render(new EmailTemplateFunction.EmailRequest("PAYMENT_APPROVED","N","en",Map.of())));}
 @Test void rejectsSensitiveVariable(){assertThrows(IllegalArgumentException.class,()->f.render(new EmailTemplateFunction.EmailRequest("REGISTRATION_WELCOME","N","en",Map.of("jwt","x"))));}}
